import { test, expect } from 'bun:test';
import { payments, reset, booked } from './payments';
import { annualReport } from './report';
import { splitCheckout, wholeCheckout, reclaimReservation } from './checkout';

test('annual report uses the payments effective predicate', () => {
  reset();
  payments.push(
    { id: 'effective', posted: true, paidAt: '2025-12-28', cents: 100 },
    { id: 'rejected', posted: true, paidAt: '2025-12-28', rejectedAt: '2026-01-01', cents: 50 },
    { id: 'draft', posted: false, paidAt: '2025-12-28', cents: 20 },
    { id: 'other-year', posted: true, paidAt: '2024-12-28', cents: 10 },
  );
  expect(annualReport(2025).cents).toBe(100);
});

test('a split booking prevents a whole retry and reservation reclaim', () => {
  reset();
  splitCheckout('one', [40, 60]);
  expect(wholeCheckout('one', 100).status).toBe('already-booked');
  expect(reclaimReservation('one')).toBe(false);
  expect(booked.size).toBe(2);
  expect(reclaimReservation('other')).toBe(true);
  expect(wholeCheckout('other', 30).status).toBe('booked');
  expect(reclaimReservation('other')).toBe(false);
});

