import { booked } from './payments';

function paymentReference(line: string, part?: number) {
  return `payment:${line}${part === undefined ? '' : `:part:${part}`}`;
}

function isPaymentReference(line: string, reference: string) {
  const whole = paymentReference(line);
  if (reference === whole) return true;
  const prefix = `${whole}:part:`;
  if (!reference.startsWith(prefix)) return false;
  const part = reference.slice(prefix.length);
  return /^(0|[1-9]\d*)$/.test(part);
}

function hasBooking(line: string) {
  return [...booked.keys()].some(reference => isPaymentReference(line, reference));
}

export function splitCheckout(line: string, parts: number[]) {
  parts.forEach((cents, i) => booked.set(paymentReference(line, i), cents));
}

export function wholeCheckout(line: string, cents: number) {
  if (hasBooking(line)) return { status: 'already-booked' };
  booked.set(paymentReference(line), cents);
  return { status: 'booked' };
}

export function reclaimReservation(line: string) {
  return !hasBooking(line);
}

